//! Lazy native dependency graphs and per-lockfile sidecar storage.
use super::{AubeLock, UvLock, hash_canonical_toml};
use eyre::{Result, bail, eyre};
use serde::{Deserialize, Serialize, de::DeserializeOwned};
use sha2::{Digest, Sha256};
use std::path::{Component, Path, PathBuf};
use std::sync::OnceLock;

pub(crate) trait NativeGraph: Clone + std::fmt::Debug + Serialize + DeserializeOwned {
    const GRAPH_FILE: &'static str;
    fn graph_text(&self) -> Result<String>;
    fn files(&self) -> Result<Vec<(&'static str, String)>>;
    fn read(dir: &Path, graph_text: String) -> Result<Self>;
}

#[derive(Clone, Debug)]
pub(crate) enum GraphRef<T> {
    Inline { graph: T, dir: Option<PathBuf>, digest: OnceLock<String> },
    Sidecar { dir: PathBuf, digest: String, cell: OnceLock<Result<T, String>> },
}

impl<T: NativeGraph> From<T> for GraphRef<T> {
    fn from(graph: T) -> Self { Self::Inline { graph, dir: None, digest: OnceLock::new() } }
}
impl<T: NativeGraph> PartialEq for GraphRef<T> {
    fn eq(&self, other: &Self) -> bool { self.identity() == other.identity() }
}
impl<T: NativeGraph> Eq for GraphRef<T> {}

pub(crate) fn digest_bytes(bytes: &[u8]) -> String {
    format!("sha256:{}", hex::encode(Sha256::digest(bytes)))
}

impl<T: NativeGraph> GraphRef<T> {
    pub(crate) fn identity(&self) -> String {
        match self {
            Self::Sidecar { digest, .. } => digest.clone(),
            Self::Inline { graph, digest, .. } => digest.get_or_init(|| digest_bytes(graph.graph_text().expect("native graph serialization").as_bytes())).clone(),
        }
    }
    pub(crate) fn dir(&self) -> Option<&Path> {
        match self { Self::Inline { dir, .. } => dir.as_deref(), Self::Sidecar { dir, .. } => Some(dir) }
    }
    pub(crate) fn keep_path_from(&mut self, old: &Self) {
        if let Self::Inline { dir, .. } = self { *dir = old.dir().map(Path::to_path_buf); }
    }
    pub(crate) fn load(&self) -> Result<&T> {
        match self {
            Self::Inline { graph, .. } => Ok(graph),
            Self::Sidecar { dir, digest, cell } => cell.get_or_init(|| {
                let text = std::fs::read_to_string(dir.join(T::GRAPH_FILE)).map_err(|e| e.to_string())?;
                if digest_bytes(text.as_bytes()) != *digest { return Err("digest mismatch; run `mise lock` to accept the edited graph".into()); }
                T::read(dir, text).map_err(|e| e.to_string())
            }).as_ref().map_err(|e| eyre!("dependency sidecar {}: {e}; run `mise lock` to repair it", dir.display())),
        }
    }
    /// Read actual bytes when accepting external edits. Keep the recorded directory.
    pub(crate) fn refresh(&self) -> Result<Self> {
        let Self::Sidecar { dir, .. } = self else { return Ok(self.clone()) };
        let text = std::fs::read_to_string(dir.join(T::GRAPH_FILE))
            .map_err(|e| eyre!("dependency sidecar {}: {e}; run `mise lock`", dir.display()))?;
        let graph = T::read(dir, text)?;
        Ok(Self::Inline { graph, dir: Some(dir.clone()), digest: OnceLock::new() })
    }
    pub(crate) fn resolve_path(&mut self, lockfile: &Path) -> Result<()> {
        if let Self::Sidecar { dir, .. } = self {
            if dir.is_absolute() || dir.components().any(|c| !matches!(c, Component::Normal(_))) || dir.to_string_lossy().contains('\\') {
                bail!("invalid dependency sidecar path {}", dir.display());
            }
            *dir = absolute(lockfile.parent().unwrap_or(Path::new("."))).join(&*dir);
        }
        Ok(())
    }
    pub(crate) fn parse(value: toml::Value) -> Result<Self> {
        if value.get("path").is_some() {
            #[derive(Deserialize)]
            #[serde(deny_unknown_fields)]
            struct Pointer { path: PathBuf, digest: String }
            let p: Pointer = value.try_into()?;
            if !p.digest.strip_prefix("sha256:").is_some_and(|s| s.len() == 64 && s.bytes().all(|b| b.is_ascii_hexdigit())) {
                bail!("invalid dependency graph digest");
            }
            Ok(Self::Sidecar { dir: p.path, digest: p.digest, cell: OnceLock::new() })
        } else {
            debug!("migrating inline dependency graph to a native sidecar on the next lockfile save");
            Ok(Self::from(value.try_into::<T>()?))
        }
    }
    pub(crate) fn pointer(&self, base: &Path) -> Result<toml::Value> {
        let dir = self.dir().ok_or_else(|| eyre!("dependency sidecar has not been prepared"))?;
        let relative = dir.strip_prefix(absolute(base))?;
        let path = relative.components().map(|c| c.as_os_str().to_string_lossy()).collect::<Vec<_>>().join("/");
        Ok(toml::toml! { path = path digest = self.identity() }.into())
    }
}

// Serde is used for legacy inline parsing and internal snapshots. Disk writes
// replace graph fields with prepared pointer values before serializing.
impl<T: NativeGraph> Serialize for GraphRef<T> {
    fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        match self {
            Self::Inline { graph, .. } => graph.serialize(serializer),
            Self::Sidecar { dir, digest, .. } => {
                use serde::ser::SerializeStruct;
                let mut s = serializer.serialize_struct("GraphRef", 2)?;
                s.serialize_field("path", dir)?;
                s.serialize_field("digest", digest)?;
                s.end()
            }
        }
    }
}
impl<'de, T: NativeGraph> Deserialize<'de> for GraphRef<T> {
    fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        Self::parse(toml::Value::deserialize(deserializer)?).map_err(serde::de::Error::custom)
    }
}

pub(crate) fn absolute(path: &Path) -> PathBuf {
    if path.is_absolute() { path.to_path_buf() } else { crate::env::current_dir().unwrap_or_default().join(path) }
}

pub(crate) fn sidecar_root(lockfile: &Path) -> PathBuf {
    let dir = lockfile.parent().unwrap_or(Path::new("."));
    let mut root = match dir.file_name().and_then(|s| s.to_str()) {
        Some(".mise") => dir.join("locks"),
        Some("mise") if dir.parent().and_then(Path::file_name).is_some_and(|s| s == ".config") => dir.join("locks"),
        Some(".config") => dir.join("mise/locks"),
        _ => dir.join(".mise/locks"),
    };
    if lockfile.file_name().is_some_and(|s| s != "mise.lock") {
        root.push(lockfile.file_stem().unwrap_or_default());
    }
    root
}

pub(crate) fn variant_suffix(backend: Option<&str>, options: &std::collections::BTreeMap<String, String>) -> String {
    let value = toml::toml! { backend = backend.unwrap_or("") options = toml::Value::try_from(options).expect("string options") };
    let mut hash = Sha256::new();
    hash_canonical_toml(&mut hash, &value.into());
    hex::encode(hash.finalize())[..8].to_owned()
}

impl NativeGraph for UvLock {
    const GRAPH_FILE: &'static str = "uv.lock";
    fn graph_text(&self) -> Result<String> {
        if self.graph_text.is_empty() { Ok(toml::to_string(&self.graph)?) } else { Ok(self.graph_text.clone()) }
    }
    fn files(&self) -> Result<Vec<(&'static str, String)>> {
        Ok(vec![("uv.lock", self.graph_text()?), ("pyproject.toml", toml::to_string(&self.project)?)])
    }
    fn read(dir: &Path, graph_text: String) -> Result<Self> {
        Ok(Self { project: std::fs::read_to_string(dir.join("pyproject.toml"))?.parse()?, graph: graph_text.parse()?, graph_text })
    }
}
impl NativeGraph for AubeLock {
    const GRAPH_FILE: &'static str = "aube-lock.yaml";
    fn graph_text(&self) -> Result<String> { self.to_yaml() }
    fn files(&self) -> Result<Vec<(&'static str, String)>> {
        let project = if let Some(project) = &self.project { project.clone() } else {
            let dependencies = self.graph.get("importers").and_then(|v| v.get(".")).and_then(|v| v.get("dependencies")).and_then(toml::Value::as_table)
                .map(|deps| deps.iter().filter_map(|(k,v)| v.get("specifier").and_then(toml::Value::as_str).map(|v| (k.clone(), v.to_owned()))).collect::<std::collections::BTreeMap<_,_>>()).unwrap_or_default();
            serde_json::to_string_pretty(&serde_json::json!({"name":"mise-npm-install","private":true,"dependencies":dependencies}))?
        };
        Ok(vec![("aube-lock.yaml", self.to_yaml()?), ("package.json", project)])
    }
    fn read(dir: &Path, graph_text: String) -> Result<Self> {
        let mut graph = Self::from_yaml(&graph_text)?;
        let project = std::fs::read_to_string(dir.join("package.json"))?;
        serde_json::from_str::<serde_json::Value>(&project)?;
        graph.project = Some(project);
        Ok(graph)
    }
}
