#[derive(Default)]
pub(super) struct SidecarWrites {
    pub files: Vec<(PathBuf, String)>,
    pub referenced: std::collections::BTreeSet<PathBuf>,
    pub root: PathBuf,
    pub remove: Vec<PathBuf>,
}
impl SidecarWrites {
    pub fn new(lockfile: &Path) -> Self { Self { root: absolute(&sidecar_root(lockfile)), ..Default::default() } }
    pub fn reserve<T: NativeGraph>(&mut self, graph: &GraphRef<T>) {
        if let Some(dir) = graph.dir().filter(|dir| dir.starts_with(&self.root)) { self.referenced.insert(dir.to_path_buf()); }
    }
    pub fn prepare<T: NativeGraph>(&mut self, graph: &GraphRef<T>, short: &str, version: &str, backend: Option<&str>, options: &std::collections::BTreeMap<String, String>) -> Result<GraphRef<T>> {
        if !crate::file::is_plain_file_name(version) { bail!("cannot store dependency sidecar for invalid version {version}"); }
        let dir = if let Some(dir) = graph.dir().filter(|dir| dir.starts_with(&self.root)) { dir.to_path_buf() } else {
            let parent = self.root.join(crate::backend::tool_directory_name(short));
            let plain = parent.join(version);
